mapper.select:
SELECT COUNT(1)
FROM t_ledger
WHERE user_id = #{userId}

SELECT id, user_id, account_id, biz_type, idempotency_key, reference_no, amount, original_amount, original_currency, fx_rate_at_settlement, balance_before, balance_after, frozen_before, frozen_after, margin_used_before, margin_used_after, created_at FROM t_ledger WHERE user_id = #{userId}
AND biz_type = #{bizTypeCode}
AND created_at >= #{fromTs}
AND created_at <= #{toTs}
ORDER BY created_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM t_ledger
WHERE user_id = #{userId}

    AND biz_type = #{bizTypeCode}


    AND created_at >= #{fromTs}


    AND created_at <= #{toTs}

SELECT
    biz_type        AS biz_type,
    SUM(amount)     AS total_amount,
    COUNT(*)        AS entry_count,
    MIN(created_at) AS first_at,
    MAX(created_at) AS last_at
FROM t_ledger
WHERE biz_type IN (6, 7)

    AND user_id = #{userId}


    AND reference_no LIKE #{referenceLike}


    AND created_at >= #{fromTs}


    AND created_at <= #{toTs}

GROUP BY biz_type

SELECT COUNT(1)
FROM t_ledger
WHERE user_id = #{userId}
  AND idempotency_key = #{idempotencyKey}
